"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3478],{68918:e=>{e.exports=JSON.parse('{"functions":[{"name":"bind","desc":"Wires `MoveButton` and `StashButton` inside `gui` to their respective server\\npackets (`ReqMovePlaceable` / `ReqStashPlaceable`) for the given `model`.\\n\\nButton clicks are debounced: only one request may be in-flight at a time.\\nWhen the server succeeds, the corresponding signal is fired:\\n- Move success \u2192 `Signals.OnPlaceableMoved`\\n- Stash success \u2192 `Signals.OnPlaceableStashed`\\n\\nThe returned `Binding` has a single method:\\n\\n**`binding:Unbind()`** \u2014 disconnects all button listeners and suppresses any\\npending success signal.  Call this when the GUI closes.  Safe to call\\nmultiple times (subsequent calls are no-ops).\\n\\n:::note Model destruction\\nWhen `model` is destroyed by the server (which happens on success before the\\nresponse arrives), button listeners are disconnected automatically.  The\\nin-flight success-signal path is preserved so callers still receive the\\n`OnPlaceableMoved` / `OnPlaceableStashed` event.\\n:::","params":[{"name":"model","desc":"The placed object whose actions are being bound.","lua_type":"Model"},{"name":"gui","desc":"Root GUI instance containing `MoveButton` and/or `StashButton`.","lua_type":"Instance"}],"returns":[{"desc":"Binding handle; call `:Unbind()` to clean up.","lua_type":"Binding"}],"function_type":"static","source":{"line":122,"path":"src/ReplicatedStorage/SharedModules/PlaceableActions.luau"}}],"properties":[],"types":[],"name":"PlaceableActions","desc":"Client-only helper that wires a placed object\'s GUI buttons (Stash / Move)\\nto the corresponding server packets, and handles the broadcast poof\\nvisual + sound that plays when any player stashes or moves a placeable.\\n\\n### Usage\\n\\n```lua\\nlocal PlaceableActions = require(SharedModules.PlaceableActions)\\n\\n-- Wire buttons when the GUI opens:\\nlocal binding = PlaceableActions.bind(placedModel, guiRoot)\\n\\n-- Clean up when the GUI closes:\\nbinding:Unbind()\\n```\\n\\n`guiRoot` must contain `ImageButton`s named **`MoveButton`** and/or\\n**`StashButton`** somewhere in its descendant tree; every match is wired, so\\na multi-page GUI may repeat them.  A missing button logs a warning but does\\nnot error.\\n\\nThe poof handler (`BroadcastPlaceablePoof` packet listener) is registered\\nautomatically on the client when the module loads; no manual init is needed.","source":{"line":70,"path":"src/ReplicatedStorage/SharedModules/PlaceableActions.luau"}}')}}]);